<script>
(() => {
 const type=document.getElementById('property_transaction_type');
 if(!type)return;
 const refresh=()=>{const rent=type.value==='rent';document.querySelectorAll('[data-property-field="rent"]').forEach(el=>el.classList.toggle('conditional-hidden',!rent));document.querySelectorAll('[data-property-field="capital"]').forEach(el=>el.classList.toggle('conditional-hidden',rent));};
 type.addEventListener('change',refresh);refresh();
})();
</script>
